1	package com.example.starter.trace.service;
2	
3	import com.example.starter.trace.BatchStatus;
4	import com.example.starter.trace.BizException;
5	import com.example.starter.trace.TestConclusion;
6	import com.example.starter.trace.dto.RapidTestRequest;
7	import com.example.starter.trace.dto.RetestRequest;
8	import com.example.starter.trace.dto.TestSubmissionResponse;
9	import com.example.starter.trace.idem.IdempotencyService;
10	import com.example.starter.trace.repo.HarvestBatchRepository;
11	import com.example.starter.trace.repo.ResidueTestRepository;
12	import com.example.starter.trace.repo.WarningRepository;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	import java.math.BigDecimal;
17	import java.time.Clock;
18	import java.time.LocalDateTime;
19	import java.util.List;
20	
21	/**
22	 * 药残检测服务：快检抑制率达到 50.00 判疑似并冻结；疑似批送定量复检且须换样；
23	 * 复检合格解除冻结，不合格维持冻结；同批同时刻仅允许一条检测链。
24	 */
25	@Service
26	public class ResidueTestService {
27	
28	    /** 疑似判定阈值：抑制率达到 50.00% 即判疑似。 */
29	    static final BigDecimal SUSPECT_THRESHOLD = new BigDecimal("50.00");
30	
31	    /** 同蜂场同花期疑似批预警阈值，恰 3 批触发。 */
32	    static final int WARNING_THRESHOLD = 3;
33	
34	    private final HarvestBatchRepository batchRepository;
35	    private final ResidueTestRepository testRepository;
36	    private final WarningRepository warningRepository;
37	    private final IdempotencyService idempotency;
38	    private final Clock clock;
39	
40	    public ResidueTestService(HarvestBatchRepository batchRepository,
41	                              ResidueTestRepository testRepository,
42	                              WarningRepository warningRepository,
43	                              IdempotencyService idempotency,
44	                              Clock clock) {
45	        this.batchRepository = batchRepository;
46	        this.testRepository = testRepository;
47	        this.warningRepository = warningRepository;
48	        this.idempotency = idempotency;
49	        this.clock = clock;
50	    }
51	
52	    /**
53	     * 幂等提交药残快检。
54	     */
55	    @Transactional
56	    public TestSubmissionResponse submitRapidTest(long batchId, RapidTestRequest request) {
57	        return idempotency.execute("RAPID_TEST", request.requestId(), List.of(batchId, request),
58	                TestSubmissionResponse.class, () -> doRapidTest(batchId, request));
59	    }
60	
61	    /**
62	     * 幂等提交定量复检。
63	     */
64	    @Transactional
65	    public TestSubmissionResponse submitRetest(long batchId, RetestRequest request) {
66	        return idempotency.execute("RETEST", request.requestId(), List.of(batchId, request),
67	                TestSubmissionResponse.class, () -> doRetest(batchId, request));
68	    }
69	
70	    private TestSubmissionResponse doRapidTest(long batchId, RapidTestRequest request) {
71	        HarvestBatchRepository.BatchRow batch = batchRepository.findByIdForUpdate(batchId)
72	                .orElseThrow(() -> BizException.notFound("采收批不存在: " + batchId));
73	        if (testRepository.findOpenChainId(batchId).isPresent()) {
74	            throw BizException.conflict("该采收批存在未闭环检测链，同批同时刻只允许一条检测链");
75	        }
76	        LocalDateTime now = LocalDateTime.now(clock);
77	        long chainId = testRepository.insertChain(batchId, now);
78	        if (!testRepository.tryOpenChainSlot(batchId, chainId)) {
79	            throw BizException.conflict("该采收批存在未闭环检测链，同批同时刻只允许一条检测链");
80	        }
81	        boolean suspected = request.inhibitionRate().compareTo(SUSPECT_THRESHOLD) >= 0;
82	        TestConclusion conclusion = suspected ? TestConclusion.SUSPECT : TestConclusion.PASS;
83	        long testId = testRepository.insertTest(chainId, batchId, "RAPID", request.sampleNo(),
84	                request.inhibitionRate(), conclusion, now);
85	        if (suspected) {
86	            batchRepository.updateStatus(batchId, BatchStatus.FROZEN);
87	            triggerWarningsIfNeeded(batch);
88	            // 疑似批等待复检，检测链保持 OPEN
89	        } else {
90	            batchRepository.updateStatus(batchId, BatchStatus.RELEASED);
91	            testRepository.closeChain(chainId, now);
92	            testRepository.releaseChainSlot(batchId);
93	        }
94	        BatchStatus after = suspected ? BatchStatus.FROZEN : BatchStatus.RELEASED;
95	        return new TestSubmissionResponse(testId, chainId, batchId, conclusion.name(),
96	                after.name(), request.inhibitionRate(), now);
97	    }
98	
99	    private TestSubmissionResponse doRetest(long batchId, RetestRequest request) {
100	        HarvestBatchRepository.BatchRow batch = batchRepository.findByIdForUpdate(batchId)
101	                .orElseThrow(() -> BizException.notFound("采收批不存在: " + batchId));
102	        Long chainId = testRepository.findOpenChainId(batchId)
103	                .orElseThrow(() -> BizException.conflict("该采收批无进行中的检测链，不能复检"));
104	        if (batch.status() != BatchStatus.FROZEN) {
