7	import org.junit.jupiter.api.Test;
8	import org.springframework.http.HttpStatus;
9	
10	import java.math.BigDecimal;
11	import java.util.List;
12	import java.util.concurrent.CountDownLatch;
13	import java.util.concurrent.ExecutorService;
14	import java.util.concurrent.Executors;
15	import java.util.concurrent.Future;
16	import java.util.concurrent.TimeUnit;
17	
18	import static org.assertj.core.api.Assertions.assertThat;
19	
20	/**
21	 * 并发边界测试：同批同时刻仅一条检测链；同 requestId 并发请求仅生效一次。
22	 * 通过门闩协调真实并发，设置超时，断言最终结果与库内数据。
23	 */
24	class TraceConcurrencyTest extends BaseTraceTest {
25	
26	    @Test
27	    void 并发快检同一采收批_仅一条检测链生效() throws Exception {
28	        long batchId = newBatch(1L);
29	        int threads = 4;
30	        ExecutorService pool = Executors.newFixedThreadPool(threads);
31	        CountDownLatch ready = new CountDownLatch(threads);
32	        CountDownLatch start = new CountDownLatch(1);
33	        try {
34	            List<Future<String>> futures = java.util.stream.IntStream.range(0, threads)
35	                    .mapToObj(i -> pool.submit(() -> {
36	                        ready.countDown();
37	                        assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
38	                        try {
39	                            TestSubmissionResponse r = residueTestService.submitRapidTest(batchId,
40	                                    new RapidTestRequest("REQ-CC-R" + i, "SMP-CC-" + i,
41	                                            new BigDecimal("60.00")));
42	                            return "OK:" + r.conclusion();
43	                        } catch (BizException e) {
44	                            return "BIZ:" + e.status().value();
45	                        }
46	                    }))
47	                    .toList();
48	            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
49	            start.countDown();
50	
