package com.example.starter.trace.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 创建来源召回请求。requestId 为幂等键；指纹覆盖蜂场、花期、原因、凭据与质检员。
 * 同蜂场同花期最多一条 ACTIVE 召回。
 */
public record CreateRecallRequest(
        @NotBlank String requestId,
        @NotNull Long apiaryId,
        @NotBlank String flowerPeriod,
        @NotBlank String reason,
        @NotBlank String credential,
        @NotBlank String inspector) {
}

package com.example.starter.trace.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 撤回来源召回请求。requestId 为幂等键；expectedVersion 为乐观锁版本，过期返回 409。
 * 须两名不同质检员持相互独立的凭据共同确认。
 */
public record WithdrawRecallRequest(
        @NotBlank String requestId,
        @NotNull Integer expectedVersion,
        @NotBlank String firstInspector,
        @NotBlank String firstCredential,
        @NotBlank String secondInspector,
        @NotBlank String secondCredential) {
}

package com.example.starter.trace.dto;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 来源召回详情响应。同时展示创建时的首次冻结清单与后来登记批次的追加关联，
 * 以及被加召回隔离标记的加工批（原加工证据保留）。
 * 时间字段均为 UTC。
 */
public record RecallResponse(
        Long id,
        Long apiaryId,
        String apiaryCode,
        String flowerPeriod,
        String reason,
        String status,
        Integer version,
        LocalDateTime createdAt,
        LocalDateTime withdrawnAt,
        List<LinkView> initialFrozenLinks,
        List<LinkView> appendedLinks,
        List<ProcessingMarkView> processingMarks) {

    /**
     * 召回隔离关联视图。
     *
     * @param status ACTIVE 隔离中 / RELEASED 已随召回撤回失效
     */
    public record LinkView(Long linkId, Long harvestBatchId, String batchNo,
                           String status, LocalDateTime createdAt) {
    }

    /**
     * 加工批召回隔离标记视图。
     *
     * @param status ACTIVE 隔离标记中 / RELEASED 已随召回撤回失效
     */
    public record ProcessingMarkView(Long processingBatchId, String processingBatchNo,
                                     String status, LocalDateTime createdAt) {
    }
}

