            assertThat(detail.initialFrozenLinks())
                    .extracting(RecallResponse.LinkView::harvestBatchId)
                    .containsExactly(released);
        } finally {
            pool.shutdownNow();
            assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
        }
    }
}

